const animal = { speak() { return 'sound'; } };
const dog = Object.create(animal);
dog.name = 'Milo';

console.log(Object.hasOwn(dog, 'name'));  // true
console.log(Object.hasOwn(dog, 'speak')); // false
console.log(dog.speak());                 // 'sound'

